  "epoch.visibleProofDeadlineAt": ["visibleProofDeadlineAt"],
  "epoch.audioCueRequestCutoffAt": ["audioCueRequestCutoffAt"],
  "epoch.proofCompletedAtPageTime": ["proofCompletedAtPageTime"],
  "releaseAnchor.baselineAttackSequence": ["releaseAnchor", "baselineAttackSequence"],
  "releaseAnchor.attackWindupSeconds": ["releaseAnchor", "attackWindupSeconds"],
  "releaseAnchor.lateWindupMaxSeconds": ["releaseAnchor", "lateWindupMaxSeconds"],
  "releaseAnchor.continuitySampleCount": ["releaseAnchor", "continuitySampleCount"],
  "releaseAnchor.continuityFirstWindup": ["releaseAnchor", "continuityFirstWindup"],
  "releaseAnchor.continuityLastWindup": ["releaseAnchor", "continuityLastWindup"],
  "releaseAnchor.continuityFirstBattleTime": ["releaseAnchor", "continuityFirstBattleTime"],
  "releaseAnchor.continuityLastBattleTime": ["releaseAnchor", "continuityLastBattleTime"],
  "releaseAnchor.handoffAtBattleTime": ["releaseAnchor", "handoffAtBattleTime"],
  "releaseAnchor.handoffAtPageTime": ["releaseAnchor", "handoffAtPageTime"],
  "witness.baselineAttackSequence": ["acceptedWitnesses", 0, "baselineAttackSequence"],
  "witness.observedAttackSequence": ["acceptedWitnesses", 0, "observedAttackSequence"],
  "witness.sourceObservedAtBattleTime": ["acceptedWitnesses", 0, "sourceObservedAtBattleTime"],
  "witness.sourceObservedAtPageTime": ["acceptedWitnesses", 0, "sourceObservedAtPageTime"],
  "witness.observedAtBattleTime": ["acceptedWitnesses", 0, "observedAtBattleTime"],
  "witness.observedAtPageTime": ["acceptedWitnesses", 0, "observedAtPageTime"],
  "witness.proofCompletedAtPageTime": ["acceptedWitnesses", 0, "proofCompletedAtPageTime"],
  "audio.observedAtPageTime": ["acceptedWitnesses", 0, "audioReceipt", "observedAtPageTime"],
  "candidate.ordinal": ["acceptedWitnesses", 0, "candidateOrdinal"],
  "candidate.baselineAttackSequence": ["acceptedWitnesses", 0, "candidateBaselineAttackSequence"],
  "candidate.attackWindupSeconds": ["acceptedWitnesses", 0, "candidateAttackWindupSeconds"],
  "candidate.anchorBattleTime": ["acceptedWitnesses", 0, "candidateAnchorBattleTime"],
  "candidate.anchorPageTime": ["acceptedWitnesses", 0, "candidateAnchorPageTime"],
  "candidate.commitWindowSeconds": ["acceptedWitnesses", 0, "candidateCommitWindowSeconds"],
  "candidate.commitDeltaSeconds": ["acceptedWitnesses", 0, "candidateCommitDeltaSeconds"],
  "contact.baselineAttackSequence": ["acceptedWitnesses", 0, "contactReceipt", "baselineAttackSequence"],
